CustomField.formula:
IF(
    OR(
        /* --- 1. ケースの初回返信済み --- */
        AND(NOT(ISBLANK(Case__c)), First_Replyed__c),

        /* --- 2. 買取案件の特定条件（最新ルール） --- */
        AND(
            NOT(ISBLANK(PurchaseOpportunity__c)),
            OR(
                /* 桝本さん・吉田さんはいつでも対象（空白含む） */
                OR(Account_MVR__c = "桝本 成也", Account_MVR__c = "吉田 志"),

                /* 近畿エリアはいつでも対象（空白含む） */
                $UserRole.Name = "近畿エリア",

                /* 関東エリア：2026/5/1以降（空白含む） */
                AND(
                    $UserRole.Name = "関東エリア",
                    OR(PurchaseOpportunity__r.PurchaseDate__c >= DATE(2026, 5, 1), ISBLANK(PurchaseOpportunity__r.PurchaseDate__c))
                ),

                /* 中部・九州・その他「エリア」ロール：2026/5/26以降（空白含む） */
                AND(
                    CONTAINS($UserRole.Name, "エリア"),
                    OR(PurchaseOpportunity__r.PurchaseDate__c >= DATE(2026, 5, 26), ISBLANK(PurchaseOpportunity__r.PurchaseDate__c))
                )
            )
        )
    ),
    "CS",
    IF(
        NOT(ISBLANK(SalesManagement__c)),
        "営業管理",
        IF(
            NOT(ISBLANK(PurchaseOpportunity__c)),
            "営業",
            IF(
                NOT(ISBLANK(Case__c)),
                "受付",
                ""
            )
        )
    )
)
